// Section headers look like `# ── Commerce / SFCC ───────────────`.
const SECTION_HEADER_RE = /^#\s*──+\s*(.+?)\s*──+\s*$/;
// Scope tags are their own comment line immediately above the KEY=value line
// (not trailing on the same line) — a trailing comment would make a blank
// placeholder look non-empty to the pre-commit .env.sample secret guard,
// which just checks whether anything follows the `=`.
const SCOPE_TAG_RE = /^#\s*scope:(shared|tier|personal|auto)\s*$/;

function parseSample() {
  const samplePath = path.join(ROOT, '.env.sample');
  const parsed = [];
  let currentSection = null;
  let pendingScope = null;
  for (const raw of fs.readFileSync(samplePath, 'utf8').split('\n')) {
    const line = raw.trim();
    const sectionMatch = line.match(SECTION_HEADER_RE);
    if (sectionMatch) {
      currentSection = sectionMatch[1];
      continue;
    }
    const scopeMatch = line.match(SCOPE_TAG_RE);
    if (scopeMatch) {
      pendingScope = scopeMatch[1];
      continue;
    }
    if (!line || line.startsWith('#')) continue;
    if (!pendingScope) continue; // a KEY=value line with no scope tag above it — not managed
    const eqIdx = line.indexOf('=');
    if (eqIdx === -1) {
      pendingScope = null;
      continue;
    }
    parsed.push({
      key: line.slice(0, eqIdx).trim(),
      value: line.slice(eqIdx + 1).trim(),
      scope: pendingScope,
      section: currentSection || 'Other',
    });
    pendingScope = null;
  }
  return parsed;
}

